// Keyword rules first (same as m2_ai.py), the local model only for what they do not recognise.
const RULES = [
  ['passport_id', /pass(port)?|reisepass|\bid\b|identit|ausweis/i], ['proof_of_address', /utility|proof of address|wohnsitz|residence/i],
  ['incorporation', /incorporat|gr[uü]ndung|formation/i], ['register_extract', /register|handelsregister|auszug|extract|good standing|incumbency/i],
  ['articles', /statut|articles|memorandum|satzung|bylaws|deed|charter/i], ['share_register', /aktienbuch|share ?register|share cert/i],
  ['resolution', /resolution|beschluss|protokoll|minutes|board/i], ['power_of_attorney', /vollmacht|power of attorney|\bpoa\b/i],
  ['kyc_compliance', /kyc|fatca|\bcrs\b|world ?check|pep|compliance|due diligence|source of (funds|wealth)/i], ['lei', /\blei\b/i],
  ['bank', /bank|account|konto|iban|statement/i], ['invoice_fee', /invoice|rechnung|honorar|\bfee\b/i],
  ['financials', /bilanz|balance|financial|jahresrechnung|annual account|audit/i], ['tax', /steuer|\btax\b|\bvat\b|mwst/i],
  ['contract', /vertrag|contract|agreement|engagement/i], ['correspondence', /brief|letter|korrespondenz|\.msg$|\.eml$/i],
];
const GENERIC = /^(scan|img|image|dsc|doc|dok|document|dokument|file|datei|neu|new|copy|kopie)?[\s_-]*[\d\s_()-]*\.[a-z0-9]{2,5}$/i;
const files = ($json.body && $json.body.files) || [];
const known = [], unknown = [];
files.forEach((f, i) => { const hit = RULES.find(([, rx]) => rx.test(f)); const base = f.split(/[\\/]/).pop();
  if (hit) known.push({ id: 'd' + i, file: f, type: hit[0], confidence: 0.9 });
  else if (GENERIC.test(base)) known.push({ id: 'd' + i, file: f, type: 'other', confidence: 0.2 });
  else unknown.push({ id: 'd' + i, file: f, type: null }); });
return [{ json: { known, unknown, types: RULES.map(r => r[0]).concat(['other']),
  ollama: $env.OLLAMA_URL || 'http://127.0.0.1:11434', model: $env.OLLAMA_MODEL || 'llama3.1:8b' } }];

const prep = $('Rules first').first().json;
let typed = [];
try { const msg = $json.message ? $json.message.content : '[]'; const parsed = JSON.parse(msg);
  typed = Array.isArray(parsed) ? parsed : (parsed.items || parsed.results || []); } catch (e) { typed = []; }
const byId = Object.fromEntries(typed.filter(x => prep.types.includes(x.value)).map(x => [x.id, x]));
const result = prep.known.map(k => ({ file: k.file, type: k.type, confidence: k.confidence, by: 'rules' }))
  .concat(prep.unknown.map(u => ({ file: u.file, type: (byId[u.id] || {}).value || 'other',
    confidence: Math.min(0.85, Number((byId[u.id] || {}).confidence) || 0), by: byId[u.id] ? prep.model : 'none' })));
return [{ json: { documents: result } }];
